var runtimeAPI;
var apiUtils = require('../util');

module.exports = {
  init: function (_runtimeAPI) {
    runtimeAPI = _runtimeAPI;
  },
  get: async function (req, res) {
    const { tenantConfigId } = await apiUtils.getUserDetails(req);
    const appId = req.query.appId;
    const appType = req.query.appType;
    try {
      const flows =  await runtimeAPI.storage.getDrafts(tenantConfigId, appId, req.query.appType);
      flows.flows = flows.flows.map(flow => {
        const { tenantConfigId, createdBy, appId, ...rest} = flow;
        return rest;
      })
      return res.json({
        success: true,
        ...flows
      });
    } catch (err) {
      res.status(500).json({ success: false, message: err.message });
    }
  },
  post: async function (req, res) {
    const { username: emailId, tenantConfigId } = await apiUtils.getUserDetails(req);
    const appId = req.query.appId;
    const appType = req.query.appType;
    const flows = req.body.flows;
    try {
      const rev = await runtimeAPI.storage.saveDrafts(
        flows,
        tenantConfigId,
        emailId,
        appId,
        appType
      );
      return res.json({ success: true, rev });
    } catch (err) {
      res.status(500).json({ success: false, message: err.message });
    }
  },
  delete: async function (req, res) {
    const { tenantConfigId } = await apiUtils.getUserDetails(req);
    const appId = req.query.appId;
    const appType = req.query.appType;
    try {
      await runtimeAPI.storage.deleteDrafts(tenantConfigId, appId, appType);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ success: false, message: err.message });
    }
  }
};
